[
  {
    "pd_harm_distress": "Picturing that train reaching those five men makes my stomach turn",
    "pda_practical_counterfactual": "If the yard foreman had radioed ahead before sending the train through"
  },
  {
    "pd_harm_distress": "My hands would probably be shaking just thinking about what could happen",
    "pda_practical_counterfactual": "the crew scheduling office should have blocked that stretch"
  },
  {
    "pd_harm_distress": "gives me a knot in my chest I can't ignore",
    "pda_practical_counterfactual": "A working alarm system on that stretch would have stopped this"
  },
  {
    "pd_harm_distress": "is enough to make my throat tight right now",
    "pda_practical_counterfactual": "If the dispatcher had double-checked the track was clear before releasing"
  },
  {
    "pd_harm_distress": "Seeing it move toward them, even in my mind, leaves me unsettled",
    "pda_practical_counterfactual": "A simple radio check between the yard and the crew beforehand"
  },
  {
    "pd_harm_distress": "imagining those five men on the tracks unaware makes my chest tighten",
    "pda_practical_counterfactual": "If someone had posted a lookout at that curve"
  },
  {
    "pd_harm_distress": "Watching that train roll toward people, even as a hypothetical, makes my hands go cold",
    "pda_practical_counterfactual": "A proper barrier at the work site entrance would have kept the train off"
  },
  {
    "pd_harm_distress": "is enough to make my breathing shallow, honestly",
    "pda_practical_counterfactual": "If maintenance crews always carried a warning beacon"
  },
  {
    "pd_harm_distress": "It genuinely upsets me to picture those five men not hearing it coming",
    "pda_practical_counterfactual": "If the signal box had flagged the track as occupied"
  },
  {
    "pd_harm_distress": "leaves a real ache in my chest",
    "pda_practical_counterfactual": "A simple checklist requiring track clearance before any train movement"
  }
]
